<?php

declare(strict_types=1);

namespace Architex\Platform\SpecForge;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use Architex\Platform\Project\ProjectContext;
use Architex\Platform\Project\ProjectPhase;
use Architex\Platform\Records\ProjectRecordService;
use PDO;
use PDOException;
use Throwable;

final readonly class SpecForgeService
{
    private const PURPOSES=['for_review','for_information','for_tender','for_construction'];
    private const DECISIONS=['approve','reject','flag'];

    public function __construct(private PDO $pdo) {}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function create(string $organisationId,string $userId,string $membershipRole,array $input): array
    {
        $this->writer($organisationId,$userId,$membershipRole);
        $projectId=$this->id($input['projectId']??null,'specforge_project_required');
        $this->project($organisationId,$projectId);
        $id=Identifier::generate();$title=$this->text($input['title']??null,220,'specforge_title_required');
        $revision=$this->text($input['revisionCode']??null,40,'specforge_revision_required');
        $purpose=$this->choice($input['issuePurpose']??null,self::PURPOSES,'specforge_issue_purpose_invalid');
        try{
            $this->pdo->prepare("INSERT INTO specforge_workspaces(id,organisation_id,project_id,title,revision_code,issue_purpose,status,version,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),:title,:revision,:purpose,'draft',1,UNHEX(:user))")
                ->execute(['id'=>$id,'organisation'=>$organisationId,'project'=>$projectId,'title'=>$title,'revision'=>$revision,'purpose'=>$purpose,'user'=>$userId]);
        }catch(PDOException $exception){if((string)$exception->getCode()==='23000')throw new SpecForgeException('specforge_workspace_revision_exists');throw$exception;}
        $this->audit($organisationId,$userId,'specforge.workspace_created','specforge_workspace',$id,['projectId'=>$projectId,'revisionCode'=>$revision,'issuePurpose'=>$purpose]);
        return $this->get($organisationId,$userId,$id);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function addSection(string $organisationId,string $userId,string $membershipRole,string $workspaceId,int $expectedVersion,array $input): array
    {
        $this->writer($organisationId,$userId,$membershipRole);$workspace=$this->draft($organisationId,$userId,$workspaceId,$expectedVersion);
        $id=Identifier::generate();$values=['id'=>$id,'organisation'=>$organisationId,'project'=>$workspace['projectId'],'workspace'=>$workspaceId,'code'=>$this->text($input['code']??null,40,'specforge_section_code_required'),'title'=>$this->text($input['title']??null,220,'specforge_section_title_required'),'discipline'=>$this->role($input['discipline']??null,'specforge_discipline_invalid'),'owner'=>$this->role($input['ownerRole']??null,'specforge_owner_role_invalid'),'reviewer'=>$this->role($input['reviewerRole']??null,'specforge_reviewer_role_invalid'),'approver'=>$this->role($input['approverRole']??null,'specforge_approver_role_invalid'),'user'=>$userId];
        $this->transaction(function()use($values,$workspaceId,$organisationId,$expectedVersion,$userId):void{
            try{$this->pdo->prepare('INSERT INTO specforge_sections(id,organisation_id,project_id,workspace_id,code,title,discipline,owner_role,reviewer_role,approver_role,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),UNHEX(:workspace),:code,:title,:discipline,:owner,:reviewer,:approver,UNHEX(:user))')->execute($values);}catch(PDOException$exception){if((string)$exception->getCode()==='23000')throw new SpecForgeException('specforge_section_code_exists');throw$exception;}
            $this->bump($organisationId,$workspaceId,$expectedVersion);
            $this->audit($organisationId,$userId,'specforge.section_created','specforge_section',$values['id'],['workspaceId'=>$workspaceId,'code'=>$values['code']]);
        });
        return $this->section($organisationId,$id,$expectedVersion+1);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function addItem(string $organisationId,string $userId,string $membershipRole,string $workspaceId,string $sectionId,int $expectedVersion,array $input): array
    {
        $this->writer($organisationId,$userId,$membershipRole);$workspace=$this->draft($organisationId,$userId,$workspaceId,$expectedVersion);$sectionId=$this->id($sectionId,'specforge_section_not_found');
        $section=$this->pdo->prepare('SELECT 1 FROM specforge_sections WHERE id=UNHEX(:section) AND workspace_id=UNHEX(:workspace) AND organisation_id=UNHEX(:organisation)');$section->execute(['section'=>$sectionId,'workspace'=>$workspaceId,'organisation'=>$organisationId]);if($section->fetchColumn()===false)throw new SpecForgeException('specforge_section_not_found');
        $id=Identifier::generate();$values=['id'=>$id,'organisation'=>$organisationId,'project'=>$workspace['projectId'],'workspace'=>$workspaceId,'section'=>$sectionId,'code'=>$this->text($input['code']??null,80,'specforge_item_code_required'),'title'=>$this->text($input['title']??null,220,'specforge_item_title_required'),'room'=>$this->optional($input['room']??'',180,'specforge_room_invalid'),'package'=>$this->optional($input['package']??'',180,'specforge_package_invalid'),'supplier'=>$this->optional($input['supplier']??'',220,'specforge_supplier_invalid'),'model'=>$this->optional($input['model']??'',220,'specforge_model_invalid'),'finish'=>$this->optional($input['finish']??'',220,'specforge_finish_invalid'),'dimensions'=>$this->optional($input['dimensions']??'',220,'specforge_dimensions_invalid'),'drawings'=>$this->json($this->references($input['drawingReferences']??[])),'clauses'=>$this->json($this->references($input['clauseReferences']??[])),'budget'=>$this->integer($input['budgetAllowanceCents']??0,0,9_000_000_000_000,'specforge_budget_invalid'),'estimate'=>$this->integer($input['estimatedCostCents']??0,0,9_000_000_000_000,'specforge_estimate_invalid'),'lead'=>$this->integer($input['leadTimeDays']??0,0,65535,'specforge_lead_time_invalid'),'client'=>($input['requiresClientDecision']??false)===true?1:0,'owner'=>$this->role($input['ownerRole']??null,'specforge_owner_role_invalid'),'reviewer'=>$this->role($input['reviewerRole']??null,'specforge_reviewer_role_invalid'),'approver'=>$this->role($input['approverRole']??null,'specforge_approver_role_invalid'),'sustainability'=>$this->optional($input['sustainability']??'',1000,'specforge_sustainability_invalid'),'warranty'=>$this->optional($input['warranty']??'',1000,'specforge_warranty_invalid'),'notes'=>$this->optional($input['notes']??'',12000,'specforge_notes_invalid'),'user'=>$userId];
        $this->transaction(function()use($values,$workspaceId,$organisationId,$expectedVersion,$userId):void{
            try{$this->pdo->prepare('INSERT INTO specforge_items(id,organisation_id,project_id,workspace_id,section_id,code,title,room_name,package_name,supplier,model_name,finish_name,dimensions,drawing_references,clause_references,budget_allowance_cents,estimated_cost_cents,lead_time_days,requires_client_decision,owner_role,reviewer_role,approver_role,sustainability,warranty,notes,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),UNHEX(:workspace),UNHEX(:section),:code,:title,:room,:package,:supplier,:model,:finish,:dimensions,:drawings,:clauses,:budget,:estimate,:lead,:client,:owner,:reviewer,:approver,:sustainability,:warranty,:notes,UNHEX(:user))')->execute($values);}catch(PDOException$exception){if((string)$exception->getCode()==='23000')throw new SpecForgeException('specforge_item_code_exists');throw$exception;}
            $this->bump($organisationId,$workspaceId,$expectedVersion);
            $this->audit($organisationId,$userId,'specforge.item_created','specforge_item',$values['id'],['workspaceId'=>$workspaceId,'code'=>$values['code'],'source'=>'human_entered']);
        });
        return $this->item($organisationId,$id,$expectedVersion+1);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function decideItem(string $organisationId,string $userId,string $membershipRole,string $itemId,array $input): array
    {
        $this->writer($organisationId,$userId,$membershipRole);if(($input['humanConfirmed']??false)!==true)throw new SpecForgeException('specforge_decision_confirmation_required');
        $action=$this->choice($input['action']??null,self::DECISIONS,'specforge_decision_invalid');$actingRole=$this->role($input['actingRole']??null,'specforge_acting_role_invalid');$reason=$this->text($input['reason']??null,500,'specforge_decision_reason_required');$itemId=$this->id($itemId,'specforge_item_not_found');
        return $this->transaction(function()use($organisationId,$userId,$itemId,$action,$actingRole,$reason):array{
            $statement=$this->pdo->prepare("SELECT LOWER(HEX(i.workspace_id)) workspace_id,LOWER(HEX(i.project_id)) project_id,i.approver_role,i.reviewer_role,w.version,w.status workspace_status FROM specforge_items i JOIN specforge_workspaces w ON w.id=i.workspace_id AND w.organisation_id=i.organisation_id WHERE i.id=UNHEX(:id) AND i.organisation_id=UNHEX(:organisation) FOR UPDATE");$statement->execute(['id'=>$itemId,'organisation'=>$organisationId]);$row=$statement->fetch();if(!is_array($row))throw new SpecForgeException('specforge_item_not_found');if($row['workspace_status']!=='draft')throw new SpecForgeException('specforge_workspace_not_draft');
            $allowed=$action==='flag'?[$row['reviewer_role'],$row['approver_role']]:[$row['approver_role']];if(!in_array($actingRole,$allowed,true)||!$this->canActAs($organisationId,$userId,$row['project_id'],$actingRole))throw new SpecForgeException('specforge_decision_role_denied');
            $status=['approve'=>'approved','reject'=>'rejected','flag'=>'flagged'][$action];$this->pdo->prepare('UPDATE specforge_items SET status=:status,decided_by=UNHEX(:user),decided_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id)')->execute(['status'=>$status,'user'=>$userId,'id'=>$itemId]);$decisionId=Identifier::generate();$this->pdo->prepare('INSERT INTO specforge_item_decisions(id,organisation_id,project_id,workspace_id,item_id,action,acting_role,reason,decided_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),UNHEX(:workspace),UNHEX(:item),:action,:role,:reason,UNHEX(:user))')->execute(['id'=>$decisionId,'organisation'=>$organisationId,'project'=>$row['project_id'],'workspace'=>$row['workspace_id'],'item'=>$itemId,'action'=>$action,'role'=>$actingRole,'reason'=>$reason,'user'=>$userId]);$this->bump($organisationId,$row['workspace_id'],(int)$row['version']);$this->audit($organisationId,$userId,'specforge.item_'.$action,'specforge_item',$itemId,['workspaceId'=>$row['workspace_id'],'actingRole'=>$actingRole,'reason'=>$reason,'decisionId'=>$decisionId]);return$this->item($organisationId,$itemId,(int)$row['version']+1);
        });
    }

    /** @return array<string,mixed> */
    public function issue(string $organisationId,string $userId,string $membershipRole,string $workspaceId,int $expectedVersion,bool $humanConfirmed,string $professionalRole,string $reason): array
    {
        $this->writer($organisationId,$userId,$membershipRole);if(!$humanConfirmed)throw new SpecForgeException('specforge_issue_confirmation_required');$professionalRole=$this->role($professionalRole,'specforge_professional_role_invalid');$reason=$this->text($reason,500,'specforge_issue_reason_required');$workspace=$this->draft($organisationId,$userId,$workspaceId,$expectedVersion);
        if(!$this->canActAs($organisationId,$userId,$workspace['projectId'],$professionalRole))throw new SpecForgeException('specforge_professional_role_denied');if($workspace['items']===[]||array_filter($workspace['items'],static fn(array$item):bool=>$item['status']!=='approved'))throw new SpecForgeException('specforge_issue_blocked');
        $snapshot=['workspaceId'=>$workspaceId,'projectId'=>$workspace['projectId'],'title'=>$workspace['title'],'revisionCode'=>$workspace['revisionCode'],'issuePurpose'=>$workspace['issuePurpose'],'status'=>'issued','version'=>$expectedVersion+1,'sections'=>$workspace['sections'],'items'=>$workspace['items'],'riskSummary'=>$workspace['riskSummary'],'professionalConfirmation'=>['confirmed'=>true,'role'=>$professionalRole,'userId'=>$userId,'reason'=>$reason],'delivery'=>['architexRecordCreated'=>true,'externalDeliveryClaimed'=>false,'emailSent'=>false,'pdfGenerated'=>false],'providers'=>['aiSuggestions'=>'unavailable','supplierOrdering'=>'unavailable','digitalSignature'=>'unavailable']];$snapshotJson=$this->json($snapshot);$sha=hash('sha256',$snapshotJson);$documentId=Identifier::generate();$revisionId=Identifier::generate();$project=$this->project($organisationId,$workspace['projectId']);
        $this->transaction(function()use($organisationId,$userId,$membershipRole,$workspaceId,$expectedVersion,$workspace,$professionalRole,$reason,$snapshotJson,$sha,$documentId,$revisionId,$project):void{
            $lock=$this->pdo->prepare("SELECT version,status FROM specforge_workspaces WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation) FOR UPDATE");$lock->execute(['id'=>$workspaceId,'organisation'=>$organisationId]);$current=$lock->fetch();if(!is_array($current)||$current['status']!=='draft')throw new SpecForgeException('specforge_workspace_not_draft');if((int)$current['version']!==$expectedVersion)throw new SpecForgeException('specforge_version_conflict');
            $this->pdo->prepare('INSERT INTO controlled_documents(id,organisation_id,project_id,title,document_type,discipline,phase,author_role,reviewer_role,current_revision_id,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),:title,\'specification\',\'general\',:phase,:author,:reviewer,UNHEX(:revision),UNHEX(:user))')->execute(['id'=>$documentId,'organisation'=>$organisationId,'project'=>$workspace['projectId'],'title'=>$workspace['title'],'phase'=>$project['currentPhase'],'author'=>$professionalRole,'reviewer'=>$professionalRole,'revision'=>$revisionId,'user'=>$userId]);
            $this->pdo->prepare("INSERT INTO document_revisions(id,organisation_id,project_id,document_id,revision_code,status,issue_purpose,notes,approved_by,approved_at,approval_reason,issued_by,issued_at,issue_reason,audit_hash,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),UNHEX(:document),:revision,'issued',:purpose,:notes,UNHEX(:approved_user),UTC_TIMESTAMP(6),:approval,UNHEX(:issued_user),UTC_TIMESTAMP(6),:reason,:hash,UNHEX(:created_user))")->execute(['id'=>$revisionId,'organisation'=>$organisationId,'project'=>$workspace['projectId'],'document'=>$documentId,'revision'=>$workspace['revisionCode'],'purpose'=>$workspace['issuePurpose'],'notes'=>'Immutable SpecForge snapshot SHA-256 '.$sha,'approved_user'=>$userId,'approval'=>'Exact SpecForge items and responsibility confirmation reviewed.','issued_user'=>$userId,'reason'=>$reason,'hash'=>$sha,'created_user'=>$userId]);
            $recordId=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($organisationId,$userId,$workspace['projectId'],$membershipRole),ProjectPhase::from($project['currentPhase']),'specforge','specification',$workspace['title'].' '.$workspace['revisionCode'],'issued',['workspaceId'=>$workspaceId,'documentId'=>$documentId,'documentRevisionId'=>$revisionId,'snapshotSha256'=>$sha,'issuePurpose'=>$workspace['issuePurpose'],'professionalRole'=>$professionalRole,'externalDeliveryClaimed'=>false],['required'=>true,'approvedBy'=>$userId,'humanApprovalConfirmed'=>true]);
            $update=$this->pdo->prepare("UPDATE specforge_workspaces SET status='issued',version=version+1,snapshot_payload=:snapshot,snapshot_sha256=:sha,document_id=UNHEX(:document),document_revision_id=UNHEX(:revision),project_record_id=UNHEX(:record),issue_reason=:reason,professional_role=:role,issued_by=UNHEX(:user),issued_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation) AND version=:version AND status='draft'");$update->execute(['snapshot'=>$snapshotJson,'sha'=>$sha,'document'=>$documentId,'revision'=>$revisionId,'record'=>$recordId,'reason'=>$reason,'role'=>$professionalRole,'user'=>$userId,'id'=>$workspaceId,'organisation'=>$organisationId,'version'=>$expectedVersion]);if($update->rowCount()!==1)throw new SpecForgeException('specforge_version_conflict');
            $this->audit($organisationId,$userId,'specforge.workspace_issued','specforge_workspace',$workspaceId,['projectId'=>$workspace['projectId'],'snapshotSha256'=>$sha,'documentRevisionId'=>$revisionId,'projectRecordId'=>$recordId,'externalDeliveryClaimed'=>false]);
        });
        return $this->get($organisationId,$userId,$workspaceId);
    }

    /** @return array<string,mixed> */
    public function get(string $organisationId,string $userId,string $workspaceId): array
    {
        $this->member($organisationId,$userId);$workspaceId=$this->id($workspaceId,'specforge_workspace_not_found');$statement=$this->pdo->prepare("SELECT LOWER(HEX(w.id)) id,LOWER(HEX(w.project_id)) project_id,w.title,w.revision_code,w.issue_purpose,w.status,w.version,w.snapshot_payload,w.snapshot_sha256,LOWER(HEX(w.document_id)) document_id,LOWER(HEX(w.document_revision_id)) document_revision_id,LOWER(HEX(w.project_record_id)) project_record_id,w.issue_reason,w.professional_role,LOWER(HEX(w.created_by)) created_by,LOWER(HEX(w.issued_by)) issued_by,DATE_FORMAT(w.issued_at,'%Y-%m-%dT%H:%i:%s.%fZ') issued_at,DATE_FORMAT(w.created_at,'%Y-%m-%dT%H:%i:%s.%fZ') created_at FROM specforge_workspaces w WHERE w.id=UNHEX(:id) AND w.organisation_id=UNHEX(:organisation)");$statement->execute(['id'=>$workspaceId,'organisation'=>$organisationId]);$row=$statement->fetch();if(!is_array($row))throw new SpecForgeException('specforge_workspace_not_found');$sections=$this->sections($organisationId,$workspaceId);$items=$this->items($organisationId,$workspaceId);$snapshot=null;if(is_string($row['snapshot_payload'])){$snapshot=json_decode($row['snapshot_payload'],true,64,JSON_THROW_ON_ERROR);if(!hash_equals((string)$row['snapshot_sha256'],hash('sha256',$this->json($snapshot))))throw new SpecForgeException('specforge_integrity_failed');}
        return['id'=>$row['id'],'projectId'=>$row['project_id'],'title'=>$row['title'],'revisionCode'=>$row['revision_code'],'issuePurpose'=>$row['issue_purpose'],'status'=>$row['status'],'version'=>(int)$row['version'],'sections'=>$sections,'items'=>$items,'riskSummary'=>$this->risk($items),'snapshot'=>$snapshot,'snapshotSha256'=>$row['snapshot_sha256'],'documentId'=>$row['document_id'],'documentRevisionId'=>$row['document_revision_id'],'projectRecordId'=>$row['project_record_id'],'issueReason'=>$row['issue_reason'],'professionalRole'=>$row['professional_role'],'createdBy'=>$row['created_by'],'issuedBy'=>$row['issued_by'],'issuedAt'=>$row['issued_at'],'createdAt'=>$row['created_at'],'externalDeliveryClaimed'=>false,'aiSuggestionsAvailable'=>false,'procurementAvailable'=>false,'pdfExportAvailable'=>false];
    }

    /** @return list<array<string,mixed>> */
    public function list(string $organisationId,string $userId,string $projectId): array
    {
        $this->member($organisationId,$userId);$this->project($organisationId,$projectId);$statement=$this->pdo->prepare('SELECT LOWER(HEX(id)) FROM specforge_workspaces WHERE organisation_id=UNHEX(:organisation) AND project_id=UNHEX(:project) ORDER BY created_at DESC,id DESC');$statement->execute(['organisation'=>$organisationId,'project'=>$projectId]);return array_map(fn(string$id):array=>$this->get($organisationId,$userId,$id),$statement->fetchAll(PDO::FETCH_COLUMN));
    }

    /** @return array<string,mixed> */private function draft(string$o,string$u,string$id,int$version):array{$workspace=$this->get($o,$u,$id);if($workspace['status']!=='draft')throw new SpecForgeException('specforge_workspace_not_draft');if($version<1||$workspace['version']!==$version)throw new SpecForgeException('specforge_version_conflict');return$workspace;}
    private function bump(string$o,string$id,int$version):void{$statement=$this->pdo->prepare("UPDATE specforge_workspaces SET version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation) AND version=:version AND status='draft'");$statement->execute(['id'=>$id,'organisation'=>$o,'version'=>$version]);if($statement->rowCount()!==1)throw new SpecForgeException('specforge_version_conflict');}
    /** @return array<string,mixed> */private function section(string$o,string$id,int$version):array{$statement=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(workspace_id)) workspace_id,code,title,discipline,owner_role,reviewer_role,approver_role FROM specforge_sections WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation)');$statement->execute(['id'=>$id,'organisation'=>$o]);$row=$statement->fetch();if(!is_array($row))throw new SpecForgeException('specforge_section_not_found');return['id'=>$row['id'],'workspaceId'=>$row['workspace_id'],'code'=>$row['code'],'title'=>$row['title'],'discipline'=>$row['discipline'],'ownerRole'=>$row['owner_role'],'reviewerRole'=>$row['reviewer_role'],'approverRole'=>$row['approver_role'],'workspaceVersion'=>$version];}
    /** @return list<array<string,mixed>> */private function sections(string$o,string$w):array{$statement=$this->pdo->prepare('SELECT LOWER(HEX(id)) id FROM specforge_sections WHERE organisation_id=UNHEX(:organisation) AND workspace_id=UNHEX(:workspace) ORDER BY code,id');$statement->execute(['organisation'=>$o,'workspace'=>$w]);return array_map(fn(string$id):array=>$this->section($o,$id,0),$statement->fetchAll(PDO::FETCH_COLUMN));}
    /** @return array<string,mixed> */private function item(string$o,string$id,int$version):array{$statement=$this->pdo->prepare("SELECT LOWER(HEX(i.id)) id,LOWER(HEX(i.workspace_id)) workspace_id,LOWER(HEX(i.section_id)) section_id,i.code,i.title,i.room_name,i.package_name,i.supplier,i.model_name,i.finish_name,i.dimensions,i.drawing_references,i.clause_references,i.budget_allowance_cents,i.estimated_cost_cents,i.lead_time_days,i.requires_client_decision,i.owner_role,i.reviewer_role,i.approver_role,i.sustainability,i.warranty,i.notes,i.status,LOWER(HEX(i.created_by)) created_by,LOWER(HEX(i.decided_by)) decided_by,DATE_FORMAT(i.decided_at,'%Y-%m-%dT%H:%i:%s.%fZ') decided_at FROM specforge_items i WHERE i.id=UNHEX(:id) AND i.organisation_id=UNHEX(:organisation)");$statement->execute(['id'=>$id,'organisation'=>$o]);$row=$statement->fetch();if(!is_array($row))throw new SpecForgeException('specforge_item_not_found');return['id'=>$row['id'],'workspaceId'=>$row['workspace_id'],'sectionId'=>$row['section_id'],'code'=>$row['code'],'title'=>$row['title'],'room'=>$row['room_name'],'package'=>$row['package_name'],'supplier'=>$row['supplier'],'model'=>$row['model_name'],'finish'=>$row['finish_name'],'dimensions'=>$row['dimensions'],'drawingReferences'=>json_decode($row['drawing_references'],true,32,JSON_THROW_ON_ERROR),'clauseReferences'=>json_decode($row['clause_references'],true,32,JSON_THROW_ON_ERROR),'budgetAllowanceCents'=>(int)$row['budget_allowance_cents'],'estimatedCostCents'=>(int)$row['estimated_cost_cents'],'leadTimeDays'=>(int)$row['lead_time_days'],'requiresClientDecision'=>(bool)$row['requires_client_decision'],'ownerRole'=>$row['owner_role'],'reviewerRole'=>$row['reviewer_role'],'approverRole'=>$row['approver_role'],'sustainability'=>$row['sustainability'],'warranty'=>$row['warranty'],'notes'=>$row['notes'],'status'=>$row['status'],'createdBy'=>$row['created_by'],'decidedBy'=>$row['decided_by'],'decidedAt'=>$row['decided_at'],'workspaceVersion'=>$version,'source'=>'human_entered'];}
    /** @return list<array<string,mixed>> */private function items(string$o,string$w):array{$statement=$this->pdo->prepare('SELECT LOWER(HEX(id)) id FROM specforge_items WHERE organisation_id=UNHEX(:organisation) AND workspace_id=UNHEX(:workspace) ORDER BY code,id');$statement->execute(['organisation'=>$o,'workspace'=>$w]);return array_map(fn(string$id):array=>$this->item($o,$id,0),$statement->fetchAll(PDO::FETCH_COLUMN));}
    /** @param list<array<string,mixed>> $items @return array<string,int|bool> */private function risk(array$items):array{$allowance=array_sum(array_column($items,'budgetAllowanceCents'));$estimate=array_sum(array_column($items,'estimatedCostCents'));$unapproved=count(array_filter($items,static fn(array$i):bool=>$i['status']!=='approved'));return['budgetAllowanceCents'=>$allowance,'estimatedCostCents'=>$estimate,'budgetDeltaCents'=>$estimate-$allowance,'overBudgetCount'=>count(array_filter($items,static fn(array$i):bool=>$i['estimatedCostCents']>$i['budgetAllowanceCents'])),'longLeadCount'=>count(array_filter($items,static fn(array$i):bool=>$i['leadTimeDays']>42)),'pendingClientDecisionCount'=>count(array_filter($items,static fn(array$i):bool=>$i['requiresClientDecision']&&$i['status']!=='approved')),'unapprovedCount'=>$unapproved,'readyToIssue'=>$items!==[]&&$unapproved===0];}
    /** @return array{currentPhase:string,leadProfessionalRole:string,createdBy:string} */private function project(string$o,string$p):array{$p=$this->id($p,'specforge_project_not_found');$statement=$this->pdo->prepare('SELECT current_phase currentPhase,lead_professional_role leadProfessionalRole,LOWER(HEX(created_by)) createdBy FROM projects WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation)');$statement->execute(['id'=>$p,'organisation'=>$o]);$row=$statement->fetch();if(!is_array($row))throw new SpecForgeException('specforge_project_not_found');return$row;}
    private function canActAs(string$o,string$u,string$p,string$role):bool{$project=$this->project($o,$p);if(hash_equals($project['createdBy'],$u)&&$project['leadProfessionalRole']===$role)return true;$statement=$this->pdo->prepare("SELECT 1 FROM project_team_members WHERE organisation_id=UNHEX(:organisation) AND project_id=UNHEX(:project) AND user_id=UNHEX(:user) AND status='active' AND discipline=:role");$statement->execute(['organisation'=>$o,'project'=>$p,'user'=>$u,'role'=>$role]);return$statement->fetchColumn()!==false;}
    private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new SpecForgeException('specforge_permission_denied');$this->member($o,$u);}
    private function member(string$o,string$u):void{$statement=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation) AND user_id=UNHEX(:user) AND status='active'");$statement->execute(['organisation'=>$o,'user'=>$u]);if($statement->fetchColumn()===false)throw new SpecForgeException('specforge_permission_denied');}
    /** @return list<string> */private function references(mixed$v):array{if(!is_array($v)||count($v)>50)throw new SpecForgeException('specforge_references_invalid');$out=[];foreach($v as$value){$value=$this->text($value,300,'specforge_references_invalid');$out[$value]=true;}return array_keys($out);}
    private function role(mixed$v,string$e):string{$v=$this->text($v,80,$e);if(preg_match('/\A[a-z][a-z0-9_]{1,79}\z/',$v)!==1)throw new SpecForgeException($e);return$v;}
    private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new SpecForgeException($e);return strtolower($v);}private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new SpecForgeException($e);return$v;}private function optional(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if(mb_strlen($v)>$m)throw new SpecForgeException($e);return$v;}private function integer(mixed$v,int$min,int$max,string$e):int{if(!is_int($v)||$v<$min||$v>$max)throw new SpecForgeException($e);return$v;}private function choice(mixed$v,array$a,string$e):string{if(!is_string($v)||!in_array($v,$a,true))throw new SpecForgeException($e);return$v;}/** @param array<mixed> $v */private function json(array$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
    /** @param array<string,mixed> $metadata */private function audit(string$o,string$u,string$action,string$type,string$id,array$metadata):void{(new AuditService($this->pdo))->append($o,$u,$action,$type,$id,$metadata);}
    private function transaction(callable$operation):mixed{$this->pdo->beginTransaction();try{$result=$operation();$this->pdo->commit();return$result;}catch(Throwable$exception){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$exception;}}
}
